/* (9090) 파일 업로드 insert를 위한 쿼리 */	
INSERT INTO CSPD006TL(                                      
		INPT_MST_SRNO                                       
		, AI_INPT_ATFL_SRNO                                 
		, AI_INPT_ATFL_NM                                   
		, AI_INPT_ATFL_PATH_TXT                             
		, TRN_LOG_SRNO                                      
		, LST_DB_CHG_ID                                     
		, LST_DB_CHG_DTM                                    
		, AI_INPT_BIZ_DSCD
	) VALUES(
		#{inptMstSrno}
		, (SELECT NVL(MAX(AI_INPT_ATFL_SRNO), 0)            
		   FROM CSPD006TL                                               
		   WHERE INPT_MST_SRNO=#{inptMstSrno}               
		   ) + 1                                            
		, #{aiInptAtflNm}
		, #{aiInptAtflPathTxt} 
		, #{trnlogsrno}                                     
		, #{lstDbChgId}
		,     
		, '3'
	)

